import { defineComponent } from 'vue';
import { Container } from 'pixi.js';

import { default as SceneElement } from './scene-element-view.vue';
import { default as DetailView } from './detail-view.vue';
import { eventEmitter } from '../../../services/event-emitter';
import { device } from '../../../services/device';
import { useCompanionState } from '../../../models/companion-state';

export interface ISceneElement {
    name: string;
    children: ISceneElement[];
    id: number;
    element: Container
}

export default defineComponent({
    name: 'DesignEditor',
    components: {
        SceneElement,
        DetailView
    },
    data() {
        return {
            showReelConfig: false,
            count: 0,
            slideText: '>',
            visible: false,
            showDetails: false,
        };
    },
    computed: {
        stageElements(): ISceneElement[] {
            if (!window.$pixi || !window.$pixi.stage) {
                return [];
            } 

            const recursiveAdd = (object: Container, parentArray: ISceneElement[]) => {
                const element: ISceneElement = {
                    name: object.constructor.name + (object.name === null ? '' : '[' + object.name + ']'),
                    children: [],
                    id: this.count,
                    element: object
                };

                this.count++;

                if (object instanceof Container) {
                    object.children.forEach((child) => {
                        recursiveAdd(child, element.children);
                    });
                }

                parentArray.push(element);
            };
            const sceneElements: ISceneElement[] = [];

            recursiveAdd(window.$pixi.stage, sceneElements);

            return sceneElements;
        },
        overlayHeight(): string {
            if (device.orientation.isLandscape) {
                return '100%';
            }
            return `${this.companion.panelHeight}px`;
        },
        overlayWidth(): string {
            if (device.orientation.isPortrait) {
                return '100%';
            } else {
                if (device.type.isDesktop) {
                    return `${this.companion.width}px`;
                }
                return '100%';
            }
        },
        isLandscape(): boolean {
            return device.orientation.isLandscape && device.type.isDesktop;
        }
    },
    setup() {
        const { chatPanelHeight, width } = useCompanionState();
        return {
            companion: {
                panelHeight: chatPanelHeight,
                width
            }
        };
    },
    mounted(): void {
        eventEmitter.addListener('DEBUG_INSPECTOR_SHOW_REQUESTED', (show) => {
            this.visible = show;
        });
    },
    methods: {
        closeClick(): void {
            eventEmitter.emit('DEBUG_INSPECTOR_SHOW_REQUESTED', false);
        },
        modeClick(): void {
            this.showReelConfig = !this.showReelConfig;
        },
        slideClick(): void {
            const element = document.getElementById('tombola-pixi-editor');
            if (element?.classList.contains('slide')) {
                element.classList.remove('slide');
                this.slideText = '>';
            } else {
                element?.classList.add('slide');
                this.slideText = '<';
            }
        },
        deselectElement(): void {
            eventEmitter.emit('DEBUG_INSPECTOR_ELEMENT_SELECTED', null);
        }
    }
});
